import { createHash, randomBytes } from 'node:crypto';
import { createWriteStream } from 'node:fs';
import { once } from 'node:events';

export interface GeneratedFile {
  path: string;
  size: number;
  /** Hex SHA-256 of the generated bytes. */
  sha256: string;
}

/**
 * Writes `size` bytes of incompressible random data without holding them in memory,
 * returning the SHA-256 so callers can verify the file after a round trip.
 */
export async function generateFile(path: string, size: number, onProgress?: (written: number) => void): Promise<GeneratedFile> {
  const out = createWriteStream(path);
  const hash = createHash('sha256');
  const chunkSize = 4 * 1024 * 1024;
  let written = 0;
  while (written < size) {
    const chunk = randomBytes(Math.min(chunkSize, size - written));
    hash.update(chunk);
    if (!out.write(chunk)) await once(out, 'drain');
    written += chunk.length;
    onProgress?.(written);
  }
  out.end();
  await once(out, 'finish');
  return { path, size, sha256: hash.digest('hex') };
}
